-- matndagidek, tarjima metodist tekshiruvini kutadi.

-- ===== Imom al-Buxoriy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Имам аль-Бухари?', fact_ru = 'Я родился в 810 году в Бухаре. Отца я потерял рано, дорогу к знанию мне открыла мать.' WHERE id = 161;
UPDATE fact_cards SET topic_ru = '«Аль-Джами ас-Сахих»', question_ru = 'Что за сборник «Аль-Джами ас-Сахих» Имама аль-Бухари?', fact_ru = 'Плод многолетнего труда — сборник достоверных хадисов. Каждый хадис я проверял по цепочке передатчиков.' WHERE id = 162;
UPDATE fact_cards SET topic_ru = 'Мои странствия', question_ru = 'Куда странствовал Имам аль-Бухари ради собирания хадисов?', fact_ru = 'Ради собирания хадисов я странствовал в Мекку, Медину, Багдад, Дамаск и Египет.' WHERE id = 163;
UPDATE fact_cards SET topic_ru = 'Сила памяти', question_ru = 'В каком возрасте и сколько тысяч хадисов Имам аль-Бухари знал наизусть?', fact_ru = 'Как сказано в источниках, в шестнадцать лет я знал наизусть несколько тысяч хадисов.' WHERE id = 164;
UPDATE fact_cards SET topic_ru = 'Моя могила', question_ru = 'Где находится могила Имама аль-Бухари?', fact_ru = 'Конец жизни я провёл в селении Хартанг близ Самарканда, там же и моя могила.' WHERE id = 165;
UPDATE fact_cards SET topic_ru = 'Моё полное имя', question_ru = 'Каким было полное имя Имама аль-Бухари?', fact_ru = 'Моё полное имя — Мухаммад ибн Исмаил аль-Бухари. Нисба «аль-Бухари» взята от названия родного города Бухары.' WHERE id = 1640;
UPDATE fact_cards SET topic_ru = 'Молитва моей матери', question_ru = 'Как, по преданиям, Имам аль-Бухари исцелился в детстве?', fact_ru = 'По преданиям, в детстве у меня ослабли глаза, и я исцелился по искренним молитвам моей матери.' WHERE id = 1641;
UPDATE fact_cards SET topic_ru = 'Мой первый шаг к знанию', question_ru = 'Примерно в каком возрасте Имам аль-Бухари начал изучать хадисы?', fact_ru = 'Заучивать хадисы я начал примерно в десять лет. Я усердно посещал уроки своих бухарских наставников.' WHERE id = 1642;
UPDATE fact_cards SET topic_ru = 'Моя поездка в Мекку', question_ru = 'В каком возрасте Имам аль-Бухари отправился в хадж?', fact_ru = 'В шестнадцать лет я отправился в хадж с матерью и братом. Затем остался в Мекке и продолжил учиться.' WHERE id = 1643;
UPDATE fact_cards SET topic_ru = 'Багдадские улемы', question_ru = 'С каким знаменитым учёным общался Имам аль-Бухари в Багдаде?', fact_ru = 'В Багдаде я встречался с крупнейшими учёными своего времени. Я вёл беседы со знаменитым учёным Ахмадом ибн Ханбалем и учился у него.' WHERE id = 1644;
UPDATE fact_cards SET topic_ru = '«Аль-Адаб аль-муфрад»', question_ru = 'Как называется книга Имама аль-Бухари о нравственности?', fact_ru = 'В книге «Аль-Адаб аль-муфрад» я собрал хадисы о нравственности, почтении к родителям и добром нраве.' WHERE id = 1645;
UPDATE fact_cards SET topic_ru = '«Ат-Тарих аль-кабир»', question_ru = 'Чему посвящён труд Имама аль-Бухари «Ат-Тарих аль-кабир»?', fact_ru = 'В труде «Ат-Тарих аль-кабир» я дал сведения о жизни тысяч людей, передававших хадисы. Эта книга помогает учёным изучать передатчиков.' WHERE id = 1646;
UPDATE fact_cards SET topic_ru = 'Мои ученики', question_ru = 'Кто были знаменитыми учениками Имама аль-Бухари?', fact_ru = 'Среди моих учеников были и Муслим ибн Хаджадж, и Абу Иса ат-Тирмизи, ставшие впоследствии знаменитыми хадисоведами.' WHERE id = 1647;
UPDATE fact_cards SET topic_ru = 'Мой шестнадцатилетний труд', question_ru = 'Сколько лет Имам аль-Бухари составлял сборник «Аль-Джами ас-Сахих»?', fact_ru = 'Свой сборник «Аль-Джами ас-Сахих» я составлял шестнадцать лет. Все эти годы терпение и труд были моими ближайшими спутниками.' WHERE id = 1648;
UPDATE fact_cards SET topic_ru = 'Мой мемориальный комплекс', question_ru = 'Когда и где был возведён мемориальный комплекс памяти Имама аль-Бухари?', fact_ru = 'Я скончался в 870 году. Много веков спустя, в 1998 году, над моей могилой близ Самарканда возвели большой мемориальный комплекс. Сегодня туда приезжают паломники из разных стран мира.' WHERE id = 1649;
UPDATE fact_cards SET topic_ru = 'Сколько хадисов я собрал', question_ru = 'Сколько хадисов собрал Имам аль-Бухари?', fact_ru = 'Я собрал около шестисот тысяч хадисов: около ста тысяч достоверных и около двухсот тысяч недостоверных я знал наизусть.' WHERE id = 1861;
UPDATE fact_cards SET topic_ru = 'Кем был мой отец', question_ru = 'Кем был отец Имама аль-Бухари?', fact_ru = 'Мой отец Исмаил был одним из выдающихся знатоков хадисов своего времени.' WHERE id = 1862;
UPDATE fact_cards SET topic_ru = 'Сколько длились мои странствия', question_ru = 'Сколько длились странствия Имама аль-Бухари?', fact_ru = 'Как пишут некоторые историки, мои странствия по чужим краям длились примерно шесть лет.' WHERE id = 1863;
UPDATE fact_cards SET topic_ru = 'Сколько трудов я написал', question_ru = 'Сколько трудов написал Имам аль-Бухари?', fact_ru = 'Я написал более двадцати трудов.' WHERE id = 1864;
UPDATE fact_cards SET topic_ru = 'Тома «Аль-Джами ас-Сахих»', question_ru = 'Из скольких томов состоит «Аль-Джами ас-Сахих»?', fact_ru = 'Мой труд «Аль-Джами ас-Сахих» состоит из четырёх томов.' WHERE id = 1865;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Имам аль-Бухари?', fact_ru = 'Я скончался 31 августа 870 года в селении Хартанг близ Самарканда.' WHERE id = 1866;

-- ===== Jaloliddin Manguberdi =====
UPDATE fact_cards SET topic_ru = 'Кто я', question_ru = 'Кем был Джалолиддин Мангуберди?', fact_ru = 'Я сын хорезмшаха Алауддина Мухаммада. После смерти отца я продолжил борьбу против монгольского нашествия.' WHERE id = 166;
UPDATE fact_cards SET topic_ru = 'Битва при Парване', question_ru = 'Когда была битва при Парване и чем она важна?', fact_ru = 'В 1221 году близ Парвана я разбил монгольское войско — это одна из немногих побед, одержанных над воинством Чингисхана.' WHERE id = 167;
UPDATE fact_cards SET topic_ru = 'Река Инд', question_ru = 'Как поступил Джалолиддин Мангуберди в битве на берегу реки Инд?', fact_ru = 'В битве на берегу реки Инд я оказался в окружении и, прыгнув с конём в реку, перебрался на другой берег.' WHERE id = 168;
UPDATE fact_cards SET topic_ru = 'Сколько длилась моя борьба', question_ru = 'Сколько длилась борьба Джалолиддина Мангуберди против монголов?', fact_ru = 'Моя борьба против монголов длилась более десяти лет — с 1220-х годов до 1231 года.' WHERE id = 169;
UPDATE fact_cards SET topic_ru = 'Завещание отца', question_ru = 'Где отец объявил Джалолиддина Мангуберди наследником трона?', fact_ru = 'Мой отец Алауддин Мухаммад в последние дни жизни объявил меня наследником трона на острове в Каспийском море.' WHERE id = 1671;
UPDATE fact_cards SET topic_ru = 'Значение моего имени', question_ru = 'Что означает слово «Мангуберди» в имени Джалолиддина Мангуберди?', fact_ru = 'Моё имя «Мангуберди» означает «Данный Богом».' WHERE id = 1672;
UPDATE fact_cards SET topic_ru = 'Край Газни', question_ru = 'Каким краем отец поручил управлять Джалолиддину Мангуберди?', fact_ru = 'Отец поручил мне управлять краем Газни. Впоследствии именно там я собрал большое войско против монголов.' WHERE id = 1673;
UPDATE fact_cards SET topic_ru = 'Наша столица Гургандж', question_ru = 'Какой город был столицей государства Хорезмшахов?', fact_ru = 'Столицей государства Хорезмшахов был город Гургандж — один из самых благоустроенных и многолюдных городов своего времени.' WHERE id = 1674;
UPDATE fact_cards SET topic_ru = 'Мой секретарь Насави', question_ru = 'Кто был личным секретарём Джалолиддина Мангуберди, написавшим о нём книгу?', fact_ru = 'Мой личный секретарь Шихабиддин Мухаммад ан-Насави оставил книгу обо мне. Это один из важнейших источников о моей жизни.' WHERE id = 1675;
UPDATE fact_cards SET topic_ru = 'Моё правление в Тебризе', question_ru = 'Какой город Джалолиддин Мангуберди сделал своей столицей в последние годы?', fact_ru = 'В последние годы борьбы я правил на землях Азербайджана; моей столицей был город Тебриз.' WHERE id = 1676;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'В каком году умер Джалолиддин Мангуберди?', fact_ru = 'Я закрыл глаза в 1231 году в горах Курдистана. А имя моё осталось в памяти народа как имя защитника Родины.' WHERE id = 1677;
UPDATE fact_cards SET topic_ru = 'Торжества 800-летия', question_ru = 'В каком году в Узбекистане отмечалось 800-летие со дня рождения Джалолиддина Мангуберди?', fact_ru = 'Я умер в 1231 году. Века спустя, в 1999 году, в Узбекистане широко отмечалось 800-летие со дня моего рождения. То, что народ помнит меня и через столько лет, наполняет моё сердце гордостью.' WHERE id = 1678;
UPDATE fact_cards SET topic_ru = 'Мой памятник в Ургенче', question_ru = 'В каком городе возведён мемориальный комплекс, посвящённый Джалолиддину Мангуберди?', fact_ru = 'Посвящённый мне мемориальный комплекс возведён в городе Ургенч Хорезмской области.' WHERE id = 1679;
UPDATE fact_cards SET topic_ru = 'Орден моего имени', question_ru = 'Когда в Узбекистане был учреждён орден имени Джалолиддина Мангуберди?', fact_ru = 'Я умер в 1231 году. Много веков спустя, в 2000 году, в Узбекистане был учреждён орден «Джалолиддин Мангуберди». Им награждают военных, проявивших мужество в защите Родины, — и для меня великая честь, что моё имя живёт рядом с отважными воинами!' WHERE id = 1680;
UPDATE fact_cards SET topic_ru = 'Моя мать и братья', question_ru = 'Кто были матерью и братьями Джалолиддина Мангуберди?', fact_ru = 'Мою мать звали Айчечак. Среди моих братьев были Акшах и Кутбуддин Озлагшах.' WHERE id = 1856;
UPDATE fact_cards SET topic_ru = 'Моя тактика при Парване', question_ru = 'Какой новый приём применил Джалолиддин в битве при Парване?', fact_ru = 'В битве при Парване я спешил своих воинов и научил их сражаться против вражеской конницы пешими — это был новый приём.' WHERE id = 1857;
UPDATE fact_cards SET topic_ru = '«Пустыня Джалали»', question_ru = 'Почему одна пустыня называется «пустыней Джалали»?', fact_ru = 'Перейдя реку Инд, я отступил в пустыню. Сегодня та пустыня зовётся моим именем — «пустыня Джалали».' WHERE id = 1858;
UPDATE fact_cards SET topic_ru = 'Битва при Эрзинджане', question_ru = 'Когда была битва при Эрзинджане?', fact_ru = '10 августа 1230 года в битве близ Эрзинджана моё войско потерпело поражение.' WHERE id = 1859;
UPDATE fact_cards SET topic_ru = 'Годы моего правления', question_ru = 'В какие годы правил Джалолиддин Мангуберди?', fact_ru = 'Я был хорезмшахом с 1220 по 1231 год.' WHERE id = 1860;
